ndently taught language."},{"query":"do you make","rationale":"Explicit bounded usage fallback for validated A1 target collocation: do you make"},{"query":"The coffee is here. What do you make","rationale":"Exact naturalized character prompt retained as bounded usage evidence after Product Quality v2 polish."}]},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing","qualityV2Remediated":true,"qualityV2RemediationVersion":1,"qualityV2Polished":true,"qualityV2PolishVersion":2}')
